{
  "per_column": [
    {
      "name": "teacher_adaptation_to_remote_format",
      "analytical_usefulness": 0.9,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Gives a genuine thematic axis (adaptation quality) well-suited to comparing satisfaction across roles/subjects. Sample readings are sound: ED-0002 'forced me to be more creative' -> creative_innovation; ED-0001 frozen sharing -> not_evident. 'not_evident' overlaps somewhat with silence but generally warranted."
    },
    {
      "name": "instructional_depth_vs_compliance",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.7,
      "hallucination_observed": true,
      "rationale": "Distinct, useful pedagogical axis. However some values overreach: ED-0004 documentary clips -> conceptual_mastery is defensible, but ED-0002 'kitchen-chemistry' -> conceptual_mastery is a confident specific about depth the text doesn't establish; ED-0001 -> surface_procedural infers instruction quality from a tech complaint. Reasonable but partly speculative."
    },
    {
      "name": "participation_barriers",
      "analytical_usefulness": 0.9,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "Strong analytical lever for satisfaction drivers. Values are well grounded: camera freezing -> technical_interference, cameras/mics off -> behavioral_muting, no barrier text -> not_present."
    },
    {
      "name": "community_and_peer_interaction",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Useful new axis; 'zero peer interaction' -> isolated_experience and silent-row NULL are both sound. 'vibrant_community' for ED-0002 is a slightly generous read of general engagement but defensible."
    },
    {
      "name": "hands_on_learning_loss",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.65,
      "hallucination_observed": true,
      "rationale": "Relevant subject-dependent axis. But some values assert facts the text is silent on: ED-0001 (algebra) and ED-0003 (reading) marked 'hands_on_essential_missing' though neither text mentions hands-on materials being missed; these are invented specifics."
    },
    {
      "name": "digital_tools_enabling_new_learning",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.8,
      "hallucination_observed": false,
      "rationale": "Meaningful axis distinct from adaptation. Readings mostly sound: documentary clips -> useful_supplement, tech-failure rows -> not_evident. Some overlap with adaptation column but adds a tools-specific angle."
    },
    {
      "name": "asynchronous_pacing_autonomy",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Good axis given recorded/self-paced satisfaction signal. ED-0004 'pause at my own pace' -> allows_rewatching is well grounded. Defaulting silent rows to all_synchronous is a slight assumption but generally reasonable."
    },
    {
      "name": "teacher_responsiveness_and_support",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Plausible satisfaction driver. Heavy NULL usage on silent rows is correct behaviour, not penalised; ED-0005 'performing to a wall' -> minimal_engagement is a sound read of responsiveness/engagement."
    },
    {
      "name": "material_resources_and_supplies",
      "analytical_usefulness": 0.65,
      "source_groundedness": 0.6,
      "hallucination_observed": true,
      "rationale": "Potentially useful but weakly supported: ED-0001 and ED-0003 marked 'severely_limited' though neither text mentions supply shortages (tech issues aren't material supplies) -- invented. ED-0002 'materials ready' -> supplied_by_teacher is also an over-read. Largely not_applicable elsewhere, limiting leverage."
    }
  ],
  "analytical_usefulness": 0.85,
  "source_groundedness": 0.78,
  "rationale": "The added columns collectively provide multiple genuine thematic axes (adaptation, barriers, community, pacing, tools, responsiveness) that directly support grouping satisfaction across role/grade/subject -- strong analytical value with limited redundancy. Groundedness is mostly good, with correct use of NULL/not_applicable for silent rows. The main weaknesses are speculative over-reads in a few columns (hands_on_learning_loss and material_resources_and_supplies assert missing hands-on/supply shortages where source text only describes tech or engagement issues; instructional_depth occasionally asserts mastery not established), yielding some hallucinated specifics but no systemic contradiction of the text."
}
